	#uni_modal .modal-content{overflow:hidden;border:0;border-radius:15px;box-shadow:0 24px 70px rgba(28,29,32,.22)}#uni_modal .modal-header{min-height:62px;padding:15px 20px;border:0;border-bottom:1px solid #ececef;border-left:4px solid #f36b21;background:#fff}#uni_modal .modal-title{font-size:16px;font-weight:650;color:#303033}#uni_modal .modal-body{max-height:72vh;padding:0;overflow:auto;background:#f5f6f8}.order-detail-modal-content{margin:14px;padding:18px 20px;border:1px solid #e5e6e9;border-radius:12px;background:#fff;box-shadow:0 7px 22px rgba(45,45,49,.05)}#uni_modal .modal-footer{display:none}#uni_modal .order-detail-modal-footer.display{display:flex!important;align-items:center;justify-content:flex-end;gap:9px;padding:13px 18px;border:0;border-top:1px solid #e7e8eb;background:#fff}.order-detail-modal-footer .btn{display:inline-flex;align-items:center;gap:7px;min-height:38px;margin:0!important;padding:8px 15px;border-radius:9px;font-size:11px;font-weight:600}.order-modal-close{border:1px solid #dadce0;color:#5e5f64;background:#fff}.order-modal-print{border:1px solid #f36b21;color:#fff;background:#f36b21;box-shadow:0 7px 16px rgba(243,107,33,.18)}.order-modal-print:hover{color:#fff;background:#df5913}@media(max-width:600px){.order-detail-modal-content{margin:8px;padding:12px}.order-detail-modal-footer .btn{flex:1}}
